import { RayBody, RayLight } from "type";
import { calculateAngle } from "utils";

import { GameScene } from "../GameScene";
import { moveShadow } from "./utils";
import { Light } from "../Light";

const debug = true;

const rayConfig = {
  shadowColor: 0x000000,
  shadowAlpha: 0.25,
};

export class Raycaster {
  constructor(
    scene: GameScene,
    // light: RayLight, bodies: RayBody[]
  ) {
    // scene.objectState.flames


    const shadows = scene.objectState.shadows.objects.map(({ x = 0, y = 0, height = 0, width = 0, type = "circle" }) => {
      if (type === "circle") {
        const shadow = scene.add.circle(
          x,
          y,
          width / 2,
          rayConfig.shadowColor,
          rayConfig.shadowAlpha,
        );
        shadow.setScale(width / shadow.width, height / shadow.height);
        return shadow;
      } else {
        const shadow = scene.add.rectangle(
          x,
          y,
          width,
          height,
          rayConfig.shadowColor,
          rayConfig.shadowAlpha,
        );
        return shadow;
      }
    });

    console.log("lightElements", scene.lightElements.static);
    scene.objectState.shadows.objects.reduce(
      (acm, shadow) => {
        const { x = 0, y = 0 } = shadow;
        scene.lightElements.static?.list.find((light) => {
          const {
            light: { x: lx, y: ly, radius },
          } = light;
          const leftTop = { x: lx - radius, y: ly - radius };
          const rightBottom = { x: lx + radius, y: ly + radius };

          if (
            x >= leftTop.x &&
            y >= leftTop.y &&
            x <= rightBottom.x &&
            y <= rightBottom.y
          ) {
            // тінь входить до цього джерела світла
            const currentSource = acm.find((current) => current.light === light);
            if (currentSource) {
              currentSource.shadows.push()
            }
          }
        });

        return acm;
      },
      [] as {
        light: Light;
        shadows: Phaser.GameObjects.Rectangle[];
      }[],
    );

    if (debug) {
      // const
      // const lightEdge = scene.add
      //   .circle(light.x, light.y, light.radius, 0xff0000)
      //   .setDepth(Infinity)
      //   .setAlpha(0.075);
      // const lines = bodies.map(({ height, width, x, y }) => {
      //   const line = new Phaser.Geom.Line(light.x, light.y, x, y);
      //   const graphics = scene.add.graphics({
      //     lineStyle: { width: 2, color: 0x00ff00 },
      //   });
      //   graphics.strokeLineShape(line);
      //   return line;
      // });
      // const defaultPositions = bodies.map(({ height, width, x, y, type }) => {
      //   scene.add.rectangle(x, y, width, height, 0xffff00, 0.1);
      // });
    }
    // shadows.forEach((shadow) => {
    //   const { height, width, x, y } = shadow;
    //   const angle = calculateAngle(light.x, light.y, x, y);
    //   const { x: moveX, y: moveY } = moveShadow(angle);
    //   // console.log("🚀 ~ ", angle, moveX, moveY);
    //   shadow.setPosition(x + width * 0.15 * moveX, y + height * 0.15 * moveY);
    // });
  }
}
